 Spinner rowSpinner(LinearLayout parent,String label,String[] values){LinearLayout row=new LinearLayout(this);row.setOrientation(0);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(10,2,8,2);row.setBackgroundColor(0xff1b1b1d);LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,42);rp.setMargins(0,1,0,1);parent.addView(row,rp);TextView name=new TextView(this);name.setText(label);name.setTextColor(0xffe0e0e0);name.setTextSize(11);row.addView(name,new LinearLayout.LayoutParams(0,-1,1));Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,values));row.addView(s,new LinearLayout.LayoutParams(0,-1,1));return s;}
 interface Pick{void go(int v);}AdapterView.OnItemSelectedListener listener(Pick x){return new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?>a,View v,int n,long l){x.go(n);}public void onNothingSelected(AdapterView<?>a){}};}
